-- Conventions used across all migrations:
--   * Primary keys are UUIDv7 (time-ordered, generated by PostgreSQL 18's uuidv7()).
--   * Instants are timestamptz stored in UTC; venue-local times use time/date plus venues.timezone.
--   * Enumerations are text columns guarded by CHECK constraints (mapped with @Enumerated(STRING)).
--   * Money is numeric(12,2) in NPR unless a currency column says otherwise.
--   * updated_at is maintained by the application (JPA), not by triggers.

CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE users (
    id                 uuid PRIMARY KEY DEFAULT uuidv7(),
    full_name          text        NOT NULL,
    phone              text        NOT NULL UNIQUE CHECK (phone ~ '^\+[1-9][0-9]{6,14}$'),
    email              citext      UNIQUE,
    password_hash      text,
    avatar_url         text,
    preferred_language text        NOT NULL DEFAULT 'en' CHECK (preferred_language IN ('en', 'ne')),
    status             text        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'DELETED')),
    phone_verified_at  timestamptz,
    email_verified_at  timestamptz,
    last_login_at      timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE user_roles (
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       text        NOT NULL CHECK (role IN ('PLAYER', 'OWNER', 'STAFF', 'ADMIN')),
    granted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role)
);

CREATE TABLE otp_codes (
    id          uuid PRIMARY KEY DEFAULT uuidv7(),
    phone       text        NOT NULL,
    code_hash   text        NOT NULL,
    purpose     text        NOT NULL CHECK (purpose IN ('LOGIN', 'VERIFY_PHONE', 'RESET_PASSWORD')),
    attempts    int         NOT NULL DEFAULT 0,
    expires_at  timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_otp_codes_phone_created ON otp_codes (phone, created_at DESC);

CREATE TABLE refresh_tokens (
    id          uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash  text        NOT NULL UNIQUE,
    device_info text,
    expires_at  timestamptz NOT NULL,
    revoked_at  timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id);

-- Firebase Cloud Messaging tokens, one per installed app
CREATE TABLE device_tokens (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token        text        NOT NULL UNIQUE,
    platform     text        NOT NULL CHECK (platform IN ('ANDROID', 'IOS', 'WEB')),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_device_tokens_user ON device_tokens (user_id);
